// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Çokgenler, özel dörtgenler ve çemberde açı-kiriş-teğet-kuvvet özellikleri (yamuk, eşkenar dörtgen, deltoid, kirişler ve teğetler dörtgeni) (kolay).
const ozMathematics16Kolay = <(String, String, List<String>, String)>[
  ('Bir dışbükey çokgenin her köşesinden yalnız birer dış açı alınarak toplandığında elde edilen açısal büyüklük, çokgenin kenar sayısı artırıldığında nasıl değişir?', 'Kenar sayısından bağımsız biçimde 360 derecede sabit kalır', ['Eklenen her yeni kenar için tam 180 derece artış gösterir', 'Kenar sayısı iki katına çıktığında açı toplamı yarıya düşer', 'Yalnızca çift kenarlı çokgenlerde 360 derece değerini alır'], 'Konveks (dışbükey) tüm çokgenlerde dış açıların ölçüleri toplamı kenar sayısına bağlı olmaksızın daima 360 derecedir.'),
  ('Ahşap bir dekoratif çerçevenin konveks onbirgen biçiminde tasarlandığı biliniyor. Bu çerçevenin yalnızca tek bir köşesi seçilerek komşu olmayan diğer köşelere gergin teller çekildiğinde kaç farklı köşegen teli elde edilir?', '8 adet köşegen teli', ['9 adet köşegen teli', '11 adet köşegen teli', '44 adet köşegen teli'], 'n kenarlı bir konveks çokgende bir köşeden kendisi ve komşu iki köşe hariç (n - 3) köşegen çizilir; 11 - 3 = 8 bulunur.'),
  ('Seramik ustası Selim, tek tip düzgün çokgen karoları aralarında hiç boşluk kalmayacak ve üst üste binmeyecek biçimde bir salon zeminine döşemek istiyor. Aşağıdaki düzgün çokgenlerden hangisi tek başına bu kaplama işini gerçekleştirebilir?', 'Düzgün altıgen biçimindeki karo', ['Düzgün beşgen biçimindeki karo', 'Düzgün sekizgen biçimindeki karo', 'Düzgün ongen biçimindeki karo'], 'Tek tip düzgün çokgenle düzlemi kaplamak için bir iç açının 360 dereceyi tam bölmesi gerekir; düzgün altıgenin 120 derecelik iç açısı 360\'ı tam 3 kez böler.'),
  ('Bir düzgün beşgenin tüm köşegenleri çizildiğinde merkezde oluşan küçük kapalı bölge hangi geometrik şekli meydana getirir?', 'Başlangıçtaki şekille benzer bir düzgün beşgen', ['Taban açıları farklı olan ikizkenar bir yamuk', 'Kenar uzunlukları farklı genel bir beşgen', 'Köşegenleri dik kesişen bir eşkenar dörtgen'], 'Düzgün beşgenin 5 köşegeni dönel simetri gereği birbirini eşit oranlarda keser ve ortada yine küçük bir düzgün beşgen sınırlar.'),
  ('Bir kenar uzunluğu 6 santimetre olan düzgün altıgen biçimindeki metal levhanın birbirine en uzak iki köşesi arasındaki doğrusal mesafe kaç santimetredir?', '12 santimetre uzaklıktadır', ['6√3 santimetre uzaklıktadır', '9√2 santimetre uzaklıktadır', '18 santimetre uzaklıktadır'], 'Düzgün altıgende en uzun köşegen simetri merkezinden geçer ve bir kenar uzunluğunun tam 2 katına eşittir; 2 × 6 = 12 cm olur.'),
  ('ABCDE düzgün beşgeninde A köşesinden karşıdaki CD kenarına indirilen dikme ayağı H noktasıdır. Bu dikme parçası [AH] ile beşgenin simetri ekseni arasındaki ilişki nedir?', 'Hem A açısının açıortayı hem de CD kenarının kenarortayıdır', ['Yalnızca A açısını iki eş parçaya böler fakat CD\'yi ortalamaz', 'CD kenarını ortalar ancak A köşesinden farklı bir açıyla çıkar', 'Beşgenin çevrel çember merkezinden geçmez ancak alanı ikiye böler'], 'Tek sayıda kenarı olan düzgün çokgenlerde bir köşeden karşı kenara inen dikme simetri eksenidir; hem açıortay hem de karşı kenarın orta dikmesidir.'),
  ('Düzgün altıgen biçimindeki bir arı peteği gözünün bir kenarı 4 milimetredir. Bu altıgen gözün karşılıklı iki paralel kenarı arasındaki dik uzaklık kaç milimetredir?', '4√3 milimetre', ['4√2 milimetre', '6 milimetre', '8 milimetre'], 'Düzgün altıgende paralel iki kenar arasındaki dik uzaklık kısa köşegen uzunluğuna, yani 30°-30°-120° üçgeninden kenarın √3 katına (4√3 mm) eşittir.'),
  ('Karton bir konveks yedigenin tek bir köşesi, kenarların üzerindeki iki iç noktadan geçen düz bir makas darbesiyle kesilip atılıyor. Geriye kalan büyük karton parçasının kenar sayısı kaç olur?', '8 kenarlı hale gelir', ['6 kenarlı hale gelir', '7 kenarlı olarak kalır', '9 kenarlı hale gelir'], 'Kesim çizgisi iki kenarın iç noktalarından geçtiği için eski bir köşe yok olurken kesim hattının uçlarında iki yeni köşe ve arada bir yeni kenar oluşur; kenar sayısı 7 + 1 = 8 olur.'),
  ('Konveks bir çokgenin dış açılarından hiçbiri geniş açı (90 dereceden büyük) değilse, bu çokgenin sahip olabileceği dar iç açıların sayısı en fazla kaçtır?', 'Hiç dar iç açısı bulunamaz', ['En fazla 1 dar iç açısı olabilir', 'En fazla 2 dar iç açısı olabilir', 'En fazla 3 dar iç açısı olabilir'], 'Bir köşedeki iç açının dar (<90°) olması için bütünleri olan dış açının geniş (>90°) olması gerekir. Hiçbir dış açı 90°\'den büyük değilse hiçbir iç açı 90°\'den küçük olamaz.'),
  ('Dışbükey bir çokgenin tüm köşelerindeki iç açılar ile dış açıların ölçüleri bir arada toplandığında 1980 derece elde edilmektedir. Bu çokgenin kenar sayısı kaçtır?', '11 kenarlıdır', ['9 kenarlıdır', '10 kenarlıdır', '13 kenarlıdır'], 'Her köşede iç açı ile dış açının toplamı 180° olduğundan n köşe için 180°·n = 1980° yazılır; buradan n = 11 bulunur.'),
  ('Merkezi etrafında saat yönünde en az 24 derece döndürüldüğünde ilk görünümüyle birebir çakışan düzgün çokgenin bir iç açısı kaç derecedir?', '156 derece', ['144 derece', '150 derece', '162 derece'], 'En küçük dönme simetri açısı merkez açıya (ve bir dış açıya) eşittir. Dış açısı 24° olan düzgün çokgenin bir iç açısı 180° - 24° = 156° olur (15 kenarlı düzgün çokgen).'),
  ('Bir düzgün altıgenin iç teğet çemberinin yarıçapının (apotem), çevrel çemberinin yarıçapına oranı kaçtır?', '√3 / 2 oranına eşittir', ['√2 / 2 oranına eşittir', '1 / 2 oranına eşittir', '2 / 3 oranına eşittir'], 'Düzgün altıgende çevrel yarıçap R = a iken merkezden kenara inen dikme (iç teğet yarıçapı) r = a√3/2\'dir; r/R oranı √3/2 olur.'),
  ('Konveks olmayan (içbükey) dört kenarlı bir bumerang şeklindeki levhada üç dar iç açının ölçüleri 32°, 43° ve 28° olarak ölçülmüştür. Levhanın içe bükülen köşesindeki dışta kalan dar girinti açısı kaç derecedir?', '103 derece', ['97 derece', '107 derece', '113 derece'], 'İçbükey dörtgende (şalvar/roket kuralı) içe bükülen köşenin dış bölgesindeki açı diğer üç iç açının toplamına eşittir: 32° + 43° + 28° = 103°.'),
  ('Dışbükey bir n-genin iç bölgesinde seçilen rastgele bir P noktası tüm köşelerle birleştirildiğinde oluşan üçgen sayısı, yalnız bir köşeden çizilen köşegenlerin oluşturduğu üçgen sayısından kaç fazladır?', 'Kenar sayısından bağımsız olarak 2 fazladır', ['Kenar sayısından bağımsız olarak 3 fazladır', 'Çokgenin kenar sayısının yarısı kadar fazladır', 'İki yöntemde de eşit sayıda üçgen oluşur'], 'İçteki bir noktayı köşelerle birleştirmek her kenara karşılık bir üçgen olmak üzere n üçgen üretir; bir köşeden çizilen köşegenler ise (n - 2) üçgen üretir. Fark daima n - (n - 2) = 2\'dir.'),
  ('Toplam 35 adet köşegeni bulunan bir düzgün çokgenin ardışık iki kenarı arasındaki iç açı kaç derecedir?', '144 derecedir', ['135 derecedir', '140 derecedir', '150 derecedir'], 'n(n - 3)/2 = 35 eşitliğinden n(n - 3) = 70 ve n = 10 bulunur. Düzgün ongenin dış açısı 360°/10 = 36°, iç açısı ise 180° - 36° = 144° olur.'),
  ('İç açılarının ölçüleri toplamı 2340 derece olan dışbükey bir çokgenin bir köşesinden en fazla kaç farklı köşegen çizilebilir?', '12 farklı köşegen', ['11 farklı köşegen', '13 farklı köşegen', '15 farklı köşegen'], '(n - 2)·180° = 2340° eşitliğinden n - 2 = 13 ve n = 15 kenar bulunur. Bir köşeden çizilebilen köşegen sayısı n - 3 = 15 - 3 = 12\'dir.'),
  ('Düzlemde eş büyüklükteki düzgün beşgen karolar yan yana dizildiğinde zeminin boşluksuz kaplanamamasının temel geometrik nedeni aşağıdakilerden hangisidir?', '108 derecelik iç açının 360 derecenin tam böleni olmaması', ['Beşgenin kenar sayısının tek tam sayı değerine sahip olması', 'Köşegen uzunluklarının kenar uzunluğuyla irrasyonel oran kurması', 'Simetri eksenlerinin karşı kenarlara dik açı yaparak inmesi'], 'Bir köşede 3 düzgün beşgen birleşirse 324° (36° boşluk kalır), 4 beşgen birleşirse 432° (taşma olur); 108 sayısı 360\'ı tam bölmediği için boşluksuz düzlemsel kaplama yapılamaz.'),
  ('Bir kenar uzunluğu 6 birim olan ABCDEF düzgün altıgeninde [BF] ve [CE] kısa köşegenleri çizilerek ortada BCFE dikdörtgeni oluşturuluyor. Bu dikdörtgenin alanı kaç birimkaredir?', '36√3 birimkare', ['18√3 birimkare', '54 birimkare', '72 birimkare'], '|BC| = 6 birimdir. 30°-30°-120° olan ABF ikizkenar üçgeninde kısa köşegen |BF| = 6√3 birimdir. BCFE dikdörtgeninin alanı 6 × 6√3 = 36√3 birimkare olur.'),
  ('Simetri ekseni sayısı ile toplam köşegen sayısı birbirine eşit olan düzgün çokgen aşağıdakilerden hangisidir?', 'Düzgün beşgen', ['Eşkenar dörtgen', 'Düzgün altıgen', 'Kare'], 'n kenarlı bir düzgün çokgenin n tane simetri ekseni ve n(n - 3)/2 tane köşegeni vardır. n = n(n - 3)/2 eşitliğinden n - 3 = 2 ve n = 5 (düzgün beşgen) bulunur.'),
  ('ABCDE düzgün beşgeninde A köşesinden [CD] kenarına inen simetri ekseni ile B köşesinden [DE] kenarına inen simetri ekseni beşgenin merkezinde kesişmektedir. Bu iki simetri ekseni arasındaki dar açı kaç derecedir?', '72 derecelik açı oluşur', ['36 derecelik açı oluşur', '54 derecelik açı oluşur', '60 derecelik açı oluşur'], 'A ve B ardışık köşelerinden merkeze gelen simetri eksenleri çevrel çemberin yarıçapları doğrultusundadır; aralarındaki merkez açı 360°/5 = 72° olur.'),
  ('Yüzey alanı 54√3 birimkare olan bir düzgün altıgenin çevresi kaç birimdir?', '36 birim çevreye sahiptir', ['24 birim çevreye sahiptir', '30 birim çevreye sahiptir', '42 birim çevreye sahiptir'], 'Altıgenin alanı 6·(a²√3 / 4) = 54√3 eşitliğinden a² = 36 ve bir kenar a = 6 birim bulunur; çevre 6 × 6 = 36 birimdir.'),
  ('Bir düzlemsel çokgenin konveks (dışbükey) olarak nitelendirilebilmesi için sağlaması gereken temel geometrik koşul aşağıdakilerden hangisidir?', 'İç bölgesindeki her nokta çiftini birleştiren doğru parçasının tamamen çokgen içinde kalması', ['Kenar uzunluklarının ve iç açılarının tamamının birbirine eşit büyüklükte olması', 'Köşegenlerinin tamamının çokgenin ağırlık merkezinde dik açıyla kesişmesi', 'Kenar sayısının çift tam sayı olması ve karşılıklı kenarlarının paralel uzanması'], 'Tanım gereği bir kümenin konveks olması, kümeden seçilen herhangi iki noktayı birleştiren doğru parçasının hiçbir noktasının küme dışına taşmaması demektir.'),
  ('Düz bir zeminde ilerleyen eğitim robotu, her 3 metrelik doğrusal yürüyüşün sonunda bulunduğu doğrultudan 15 derece sağa dönmektedir. Robot ilk harekete başladığı noktaya ilk kez ulaştığında toplam kaç metre yürümüş olur?', '72 metre yürümüş olur', ['60 metre yürümüş olur', '48 metre yürümüş olur', '90 metre yürümüş olur'], 'Robotun her köşede döndüğü 15° bir düzgün çokgenin dış açısıdır. Toplam 360°/15° = 24 dönüşte (24 kenar) başlangıca kapanır; toplam yol 24 × 3 = 72 metredir.'),
  ('ABCDE düzgün beşgeninde A açısının açıortayı ile [BE] köşegeni K noktasında kesişmektedir. Buna göre AKB açısının ölçüsü kaç derecedir?', '90 derece ölçülür', ['72 derece ölçülür', '108 derece ölçülür', '84 derece ölçülür'], 'ABE ikizkenar üçgeninde (|AB| = |AE|) tepe açısı olan A\'nın açıortayı aynı zamanda tabana ([BE]) ait yüksekliktir; bu nedenle m(AKB) = 90° olur.'),
  ('Bir konveks çokgenin kenar sayısı 3 artırıldığında iç açılarının ölçüleri toplamında meydana gelen artış kaç derecedir?', '540 derece artar', ['360 derece artar', '720 derece artar', '180 derece artar'], 'İç açılar toplamı (n - 2)·180° formülüyle verildiğinden n yerine (n + 3) yazıldığında toplam 3 × 180° = 540° artış gösterir.'),
  ('Toplam köşegen sayısı kenar sayısının 3,5 katına eşit olan bir düzgün çokgende bir iç açının bir dış açıya oranı kaçtır?', '4 katına eşittir', ['3 katına eşittir', '5 katına eşittir', '6 katına eşittir'], 'n(n - 3)/2 = (7/2)n eşitliğinden n = 10 bulunur. Düzgün ongenin dış açısı 36°, iç açısı 144° olup oran 144/36 = 4\'tür.'),
  ('Dışbükey bir altıgenin dış açıları 1, 2, 3, 3, 4 ve 5 sayılarıyla doğru orantılıdır. Bu altıgenin en küçük iç açısının ölçüsü kaç derecedir?', '80 derecedir', ['60 derecedir', '100 derecedir', '75 derecedir'], 'Orantı sabiti k ise dış açılar toplamı 18k = 360° olup k = 20° bulunur. En büyük dış açı 5 × 20° = 100° olduğundan ona komşu olan en küçük iç açı 180° - 100° = 80° olur.'),
  ('Dışbükey bir beşgenin dört iç açısının aritmetik ortalaması 112 derece olduğuna göre beşinci köşedeki iç açının ölçüsü kaç derecedir?', '92 derece olur', ['88 derece olur', '96 derece olur', '108 derece olur'], 'Dört iç açının toplamı 4 × 112° = 448° eder. Beşgenin iç açıları toplamı (5 - 2)·180° = 540° olduğundan beşinci açı 540° - 448° = 92° bulunur.'),
  ('Herhangi bir dışbükey dörtgenin ardışık kenarlarının orta noktaları sırasıyla birleştirildiğinde elde edilen Varignon dörtgeni her durumda hangi özel geometrik sınıfın üyesidir?', 'Karşılıklı kenarları paralel bir paralelkenardır', ['Köşegenleri eşit uzunlukta bir dikdörtgendir', 'Tüm kenarları birbirine eşit eşkenar dörtgendir', 'Yalnız iki kenarı paralel olan ikizkenar yamuktur'], 'Üçgende orta taban teoremi gereği, dörtgenin karşılıklı iki kenarının orta noktalarını birleştiren parçalar ortak köşegene paralel ve onun yarısı uzunluğundadır; bu durum daima bir paralelkenar üretir.'),
  ('Köşegen uzunlukları 14 santimetre ve 22 santimetre olan konveks bir ABCD dörtgeninin kenarlarının orta noktalarını köşe kabul eden dörtgenin çevresi kaç santimetredir?', '36 santimetre çevreye sahiptir', ['18 santimetre çevreye sahiptir', '44 santimetre çevreye sahiptir', '72 santimetre çevreye sahiptir'], 'Orta noktaların oluşturduğu Varignon paralelkenarının kenarları e/2 = 7 cm ve f/2 = 11 cm olduğundan çevresi 2·(7 + 11) = e + f = 14 + 22 = 36 cm olur.'),
  ('Bir uçurtma tasarımında kullanılan dışbükey dörtgenin köşegen uzunlukları 12 desimetre ve 15 desimetre olup köşegenler arasındaki dar açı 30 derecedir. Uçurtmanın yüzey alanı kaç desimetrekaredir?', '45 desimetrekare alan kaplar', ['90 desimetrekare alan kaplar', '45√3 desimetrekare alan kaplar', '60 desimetrekare alan kaplar'], 'Genel dörtgenin alanı (1/2)·|AC|·|BD|·sinα bağıntısıyla hesaplanır: (1/2)·12·15·sin30° = 90·(1/2) = 45 dm² bulunur.'),
  ('ABCD konveks dörtgeninde komşu A ve B köşelerine ait iç açıortaylar dörtgenin içindeki P noktasında kesişmektedir. m(C) = 110° ve m(D) = 78° olduğuna göre APB açısı kaç derecedir?', '94 derecelik açı oluşturur', ['86 derecelik açı oluşturur', '96 derecelik açı oluşturur', '104 derecelik açı oluşturur'], 'Dörtgende komşu iki iç açıortayın oluşturduğu açı, diğer iki iç açının aritmetik ortalamasına eşittir: m(APB) = (110° + 78°)/2 = 94°.'),
  ('Konveks bir dörtgenin iki köşegeni çizildiğinde dörtgenin iç bölgesi dört ayrı üçgensel bölgeye ayrılmaktadır. Karşılıklı konumda bulunan iki üçgenin alanları 6 cm² ve 24 cm² olup diğer iki üçgenden birinin alanı 9 cm² ise dördüncü üçgenin alanı kaç cm² olur?', '16 santimetrekare olur', ['12 santimetrekare olur', '18 santimetrekare olur', '15 santimetrekare olur'], 'Köşegenlerin ayırdığı karşılıklı üçgenlerin alanları çarpımı birbirine eşittir (S1·S3 = S2·S4). 6 × 24 = 9 × S4 eşitliğinden 144 / 9 = 16 cm² bulunur.'),
  ('Alt tabanı [AB] = 19 santimetre ve üst tabanı [DC] = 7 santimetre olan bir ABCD yamuğunda yan kenarların orta noktalarını birleştiren orta taban çiziliyor. Yamuğun köşegenleri bu orta taban üzerinde kaç santimetrelik bir parça ayırır?', '6 santimetrelik parça ayırır', ['13 santimetrelik parça ayırır', '8 santimetrelik parça ayırır', '12 santimetrelik parça ayırır'], 'Yamukta köşegenlerin orta taban üzerinde sınırladığı doğru parçasının uzunluğu tabanlar farkının yarısına eşittir: (19 - 7) / 2 = 6 cm.'),
  ('Bir ikizkenar yamuğun üst taban uzunluğu 7 santimetre, alt taban uzunluğu 17 santimetre ve taban açılarından her biri 45 derecedir. Bu yamuğun alanı kaç santimetrekaredir?', '60 santimetrekare', ['48 santimetrekare alana sahiptir', '72 santimetrekare alana sahiptir', '84 santimetrekare'], 'Üst köşelerden tabana dikmeler indirildiğinde iki yanda (17 - 7)/2 = 5\'er cm\'lik parçalar ayrılır. Taban açısı 45° olduğundan ikizkenar dik üçgenden yükseklik h = 5 cm bulunur; alan ((17 + 7)/2) × 5 = 60 cm² eder.'),
  ('Bir ABCD paralelkenarında ardışık iki köşedeki iç açıların ölçüleri arasında m(B) = 3·m(A) - 20° bağıntısı bulunmaktadır. Buna göre paralelkenarın geniş açılarından birinin ölçüsü kaç derecedir?', '130 derece', ['125 derece ölçüsündedir', '135 derece ölçüsündedir', '140 derece'], 'Paralelkenarda komşu iki iç açı bütünlerdir: m(A) + (3·m(A) - 20°) = 180° => 4·m(A) = 200° => m(A) = 50° bulunur; geniş açı m(B) = 180° - 50° = 130° olur.'),
  ('Bir paralelkenarın dört iç açıortayı çizilip paralelkenarın iç bölgesinde birbirleriyle kesiştirildiğinde sınırladıkları küçük dörtgensel bölge her zaman hangi özel şekli oluşturur?', 'Köşeleri dik açılı bir dikdörtgen', ['Kenarları eşit bir eşkenar dörtgen', 'Yalnız iki kenarı paralel dik yamuk', 'Köşegenleri dik kesişen bir deltoid'], 'Paralelkenarda komşu iki iç açının toplamı 180° olduğundan komşu açıortaylar birbirini 90° açıyla keser; dört köşesi de 90° olan içteki dörtgen (kenarları eşit değilse) daima bir dikdörtgendir.'),
  ('ABCD paralelkenarında [DC] kenarı üzerinde 2·|DE| = 3·|EC| oranını sağlayan bir E noktası işaretleniyor. [AE] doğru parçası ile [BD] köşegeni K noktasında kesiştiğine göre Alan(DEK) / Alan(ABK) oranı kaçtır?', '9 / 25 oranındadır', ['3 / 5 oranında bulunur', '4 / 25 oranında bulunur', '9 / 16 oranındadır'], '|DE| = 3k ve |EC| = 2k alınırsa |AB| = |DC| = 5k olur. [DE] // [AB] kelebek benzerliğinden benzerlik oranı 3/5 olup alanlar oranı bunun karesine yani (3/5)² = 9/25 değerine eşittir.'),
  ('ABCD paralelkenarında A köşesinden çizilen [AC] köşegenine B köşesinden indirilen dikme ayağı H noktasıdır. |AH| = 9 birim, |HC| = 4 birim ve D noktasından [AC]\'ye çizilen doğru parçası yerine B\'den inen |BH| = 6 birim ise |AD| kenarı kaç birimdir?', '2√13 birim', ['√52 + 1 birim uzunluğundadır', '3√6 birim uzunluğundadır', '8 birim uzunluğundadır'], 'BHC dik üçgeninde dik kenarlar |HC| = 4 birim ve |BH| = 6 birim olduğundan Pisagor teoreminden |BC| = √(4² + 6²) = √52 = 2√13 birim bulunur; paralelkenarda |AD| = |BC| = 2√13 birimdir.'),
  ('Çevresi 52 santimetre olan bir eşkenar dörtgenin köşegenlerinden birinin uzunluğu 10 santimetredir. Bu eşkenar dörtgenin kapladığı alan kaç santimetrekaredir?', '120 santimetrekare', ['100 santimetrekare alana sahiptir', '130 santimetrekare alana sahiptir', '240 santimetrekare'], 'Eşkenar dörtgenin bir kenarı 52 / 4 = 13 cm\'dir. Köşegenler birbirini dik ortaladığından yarı köşegen 5 cm olup 5-12-13 dik üçgeninden diğer yarı köşegen 12 cm (tamamı 24 cm) bulunur; alan (10 × 24)/2 = 120 cm² olur.'),
  ('Bir eşkenar dörtgen ile bir dikdörtgenin köşegen özellikleri karşılaştırıldığında, yalnız eşkenar dörtgene özgü olup genel bir dikdörtgende bulunmayan özellik aşağıdakilerden hangisidir?', 'Köşegenlerin iç açıları ortalaması ve dik kesişmesi', ['Köşegenlerin birbirini tam orta noktalarından kesmesi', 'Köşegen uzunluklarının birbirine daima eşit çıkması', 'Bir köşegenin dörtgen alanını iki eş parçaya bölmesi'], 'Her iki dörtgen de paralelkenar olduğundan köşegenleri birbirini ortalar ve alanı ikiye böler; köşegen eşitliği dikdörtgene, köşegenlerin dik kesişip açıortay olması ise eşkenar dörtgene özgüdür.'),
  ('ABCD eşkenar dörtgeninde m(BAD) = 50° olarak verilmiştir. [BC] kenarı üzerine eşkenar dörtgenin dış bölgesine doğru bir BCE eşkenar üçgeni inşa edildiğine göre DCE açısının ölçüsü kaç derecedir?', '110 derece', ['105 derece ölçüsündedir', '115 derece ölçüsündedir', '130 derece'], 'Eşkenar dörtgende karşılıklı açılar eşit ve komşu açılar bütünler olduğundan m(BCD) = m(BAD) = 50° olur. Dışarıya çizilen eşkenar üçgenden m(BCE) = 60° geldiğinden m(DCE) = 50° + 60° = 110° bulunur.'),
  ('ABCD dikdörtgeninde D köşesinden [AC] köşegenine indirilen dikme ayağı H noktasıdır. |AH| = 4 birim ve |HC| = 9 birim olarak ölçüldüğüne göre bu dikdörtgenin alanı kaç birimkaredir?', '78 birimkare', ['39 birimkare alana sahiptir', '72 birimkare alana sahiptir', '65 birimkare'], 'ADC dik üçgeninde Öklid yükseklik bağıntısından |DH|² = |AH|·|HC| = 4 × 9 = 36 => |DH| = 6 birimdir. Köşegen |AC| = 4 + 9 = 13 birim olup Alan(ADC) = (13 × 6)/2 = 39 br² ve dikdörtgenin alanı 2 × 39 = 78 br² bulunur.'),
  ('Çevresi 34 metre ve köşegen uzunluğu 13 metre olan dikdörtgen biçimindeki bir bahçenin yüzey alanı kaç metrekaredir?', '60 metrekare', ['52 metrekare alana sahiptir', '65 metrekare alana sahiptir', '72 metrekare'], 'Kenarlar a ve b ise 2(a + b) = 34 => a + b = 17 m ve Pisagor\'dan a² + b² = 13² = 169 olur. (a + b)² = 289 => 169 + 2ab = 289 => 2ab = 120 => Alan = ab = 60 m² bulunur (5-12-13 üçgeni).'),
  ('Kenar uzunlukları 12 santimetre ve 18 santimetre olan bir ABCD dikdörtgeninin her bir kenarının orta noktası sırasıyla birleştirilerek bir dörtgen elde ediliyor. Elde edilen bu iç dörtgenin türü ve alanı aşağıdakilerden hangisidir?', 'Alanı 108 cm² olan eşkenar dörtgen', ['Alanı 108 cm² olan bir dikdörtgen', 'Alanı 144 cm² olan eşkenar dörtgen', 'Alanı 96 cm² olan bir paralelkenar'], 'Dikdörtgenin köşegenleri birbirine eşit olduğundan kenar ortalarını birleştiren Varignon dörtgeni bir eşkenar dörtgendir; köşegenleri 12 cm ve 18 cm olduğundan alanı (12 × 18)/2 = 108 cm² olur.'),
  ('Köşegen uzunluğu 6√2 santimetre olan bir karenin çevresi ile sayısal olarak aynı değere sahip alana ulaşan başka bir karenin bir kenar uzunluğu kaç santimetredir?', '2√6 santimetre', ['4√2 santimetre uzunluğundadır', '6 santimetre uzunluğundadır', '3√3 santimetre'], 'Köşegeni 6√2 cm olan ilk karenin bir kenarı 6 cm, çevresi ise 4 × 6 = 24 cm\'dir. Alanı 24 cm² olan ikinci karenin bir kenarı √24 = 2√6 cm bulunur.'),
  ('ABCD karesinin [AC] köşegeni üzerinde |AE| = 2 santimetre ve |EC| = 14 santimetre olacak biçimde bir E noktası işaretleniyor. Karenin B köşesi ile E noktasını birleştiren [BE] doğru parçasının uzunluğu kaç santimetredir?', '10 santimetre', ['8√2 santimetre uzunluğundadır', '6√3 santimetre uzunluğundadır', '12 santimetre'], 'Karenin köşegenleri birbirini dik ortalar; |AC| = 2 + 14 = 16 cm olduğundan kesim noktası O için |AO| = |BO| = 8 cm ve |EO| = 8 - 2 = 6 cm olur. EOB dik üçgeninde 6-8-10 üçgeninden |BE| = 10 cm bulunur.'),
  ('Bir kenarı 10 birim olan bir karenin iç bölgesinde seçilen P noktası dört köşeyle birleştirildiğinde oluşan dört üçgenden Alan(PAB) = 18 birimkare olduğuna göre karşı konumda yer alan Alan(PCD) kaç birimkaredir?', '32 birimkare', ['22 birimkare alana sahiptir', '28 birimkare alana sahiptir', '36 birimkare'], 'Kare (ve paralelkenar) içinde alınan bir noktanın karşılıklı kenarlarla oluşturduğu iki üçgenin alanları toplamı tüm alanın yarısına eşittir. Karenin alanı 100 br² olduğundan Alan(PAB) + Alan(PCD) = 50 => 18 + Alan(PCD) = 50 => Alan(PCD) = 32 br² bulunur.'),
  ('Kare biçimindeki bir kağıt önce dikey, ardından yatay simetri ekseni boyunca iki kez katlanarak dört katlı küçük bir kare elde ediliyor. Kağıdın orijinal merkezine karşılık gelen kapalı köşeden kat izlerine 45° açı yapan küçük bir ikizkenar dik üçgen kesilip kağıt açıldığında ortada oluşan delik hangi şekildir?', 'Köşegenleri kat izleri üzerinde olan kare', ['Yalnız tek köşegeni eşit olan bir deltoid', 'Kenarları dış kareye paralel olmayan yamuk', 'Düzgün altıgen biçiminde merkezi bir delik'], 'Kapalı merkez köşesinden eşit dik kenarlarla yapılan doğrusal kesim, iki dik kat eksenine göre yansıtıldığında köşegenleri eşit ve dik kesişen (yani kare olan) merkezi bir iç boşluk üretir.'),
  ('Tabanları çakışık iki farklı ikizkenar üçgenin tabanın zıt taraflarında birleştirilmesiyle oluşan deltoidde simetri ekseni olan köşegen için aşağıdakilerden hangisi her zaman doğrudur?', 'Diğer köşegeni dik keser ve iki eş parçaya böler', ['Diğer köşegen tarafından tam ortasından ikiye bölünür', 'Karşılıklı tüm iç açıları dört eş açıya ayırır', 'Uzunluğu daima diğer köşegenin uzunluğundan büyüktür'], 'Deltoidde ikizkenar üçgenlerin tepe noktalarını birleştiren ana köşegen (simetri ekseni), ortak taban olan diğer köşegeni dik açıyla ortalar ve kendi uçlarındaki tepe açılarını ikiye böler.'),
  ('|AB| = |AD| ve |CB| = |CD| koşullarını sağlayan bir ABCD deltoidinde m(A) = 74° ve m(C) = 46° olarak ölçülmüştür. Buna göre deltoidin eş olan yan açılarından ABC açısı kaç derecedir?', '120 derece', ['110 derece ölçüsündedir', '115 derece ölçüsündedir', '125 derece'], 'Deltoidde simetri ekseni dışında kalan karşılıklı B ve D açıları birbirine eşittir: 74° + 46° + 2·m(B) = 360° => 2·m(B) = 240° => m(ABC) = 120° bulunur.'),
  ('Bir ABCD deltoidinde |AB| = |AD| = 10 santimetre, |BC| = |DC| = 17 santimetre ve simetri ekseni olmayan [BD] köşegeninin uzunluğu 16 santimetredir. Bu deltoidin alanı kaç santimetrekaredir?', '168 santimetrekare', ['144 santimetrekare alana sahiptir', '156 santimetrekare alana sahiptir', '180 santimetrekare'], 'Köşegenlerin dik kesim noktası O için |BO| = |OD| = 8 cm olur. 6-8-10 üçgeninden |AO| = 6 cm ve 8-15-17 üçgeninden |OC| = 15 cm olduğundan |AC| = 21 cm ve Alan = (16 × 21)/2 = 168 cm² bulunur.'),
  ('Konveks bir ABCD deltoidinde |AB| = |AD| = 6 birim, |BC| = |CD| = 8 birim ve m(ABC) = 90° olarak verilmiştir. Bu deltoidin simetri ekseni olan [AC] köşegeninin uzunluğu kaç birimdir?', '10 birimdir', ['2√14 birim uzunluğundadır', '4,8 birim uzunluğundadır', '9,6 birimdir'], 'ABC üçgeni m(B) = 90° olan ve dik kenarları |AB| = 6 birim, |BC| = 8 birim olan bir dik üçgendir; hipotenüsü olan [AC] köşegeni 6-8-10 üçgeninden doğrudan 10 birimdir.'),
  ('Bir çemberde çapı gören çevre açının ölçüsü kaç derecedir?', '90 derece', ['45 derece', '60 derece', '180 derece'], 'Çap çemberi 180 derecelik iki eş yaya böler; çevre açı gördüğü yayın yarısına eşit olduğundan ölçüsü 90 derecedir.'),
  ('Bir çemberde aynı yayı gören merkez açı ile çevre açı arasında nasıl bir bağıntı vardır?', 'Merkez açı çevre açının iki katıdır', ['Çevre açı merkez açının iki katıdır', 'Merkez açı ile çevre açı birbirine eşittir', 'Merkez açı çevre açının üç katıdır'], 'Merkez açı gördüğü yayın ölçüsüne, çevre açı ise gördüğü yayın yarısına eşit olduğundan merkez açı çevre açının iki katıdır.'),
  ('Bir çemberde 70 derecelik bir yayı gören teğet-kiriş açının ölçüsü kaç derecedir?', '35 derece', ['70 derece', '110 derece', '140 derece'], 'Teğet-kiriş açının ölçüsü, tıpkı çevre açı gibi gördüğü yayın ölçüsünün yarısına eşittir; 70 / 2 = 35 derecedir.'),
  ('Köşeleri aynı çember üzerinde bulunan bir kirişler dörtgeninde karşılıklı iki açının ölçüleri toplamı kaç derecedir?', '180 derece', ['90 derece', '270 derece', '360 derece'], 'Kirişler dörtgeninde karşılıklı açılar çemberin tamamını (360 dereceyi) gören çevre açılar olduğu için toplamları 180 derecedir.'),
  ('Bir çemberin merkezinden 16 santimetre uzunluğundaki bir kirişe indirilen dikme, kirişi kaçar santimetrelik parçalara ayırır?', '8 ve 8 santimetre', ['6 ve 10 santimetre', '4 ve 12 santimetre', '7 ve 9 santimetre'], 'Çemberin merkezinden kirişe indirilen dikme kirişi her zaman iki eş parçaya böler; 16 / 2 = 8 santimetredir.'),
  ('Bir çembere dışındaki bir P noktasından çizilen iki teğet parçasının değme noktaları A ve B ise |PA| ile |PB| uzunlukları arasındaki ilişki nedir?', 'Birbirine eşittir', ['Biri diğerinin iki katıdır', 'Toplamları çemberin çapına eşittir', 'Çarpımları yarıçapın karesine eşittir'], 'Çembere dışındaki bir noktadan çizilen iki teğet parçasının uzunlukları daima birbirine eşittir.'),
  ('Yarıçapı 10 santimetre olan bir çemberin merkezinden 6 santimetre uzaklıktaki kirişin uzunluğu kaç santimetredir?', '16 santimetre', ['8 santimetre', '12 santimetre', '14 santimetre'], 'Merkezden kirişe indirilen dikme kirişi ikiye böler; 6-8-10 dik üçgeninden yarım kiriş 8 santimetre ve tüm kiriş 16 santimetredir.'),
  ('Bir teğetler dörtgeninin karşılıklı iki kenarının uzunlukları 9 santimetre ve 13 santimetre ise bu dörtgenin çevresi kaç santimetredir?', '44 santimetre', ['22 santimetre', '36 santimetre', '52 santimetre'], 'Teğetler dörtgeninde karşılıklı kenar uzunlukları toplamı birbirine eşittir; 9 + 13 = 22 olduğundan çevre 22 x 2 = 44 santimetredir.'),
  ('Bir çemberin dışındaki bir noktadan çembere çizilen iki teğet arasındaki açı 50 derece ise teğetlerin değme noktaları arasında kalan küçük yayın ölçüsü kaç derecedir?', '130 derece', ['50 derece', '100 derece', '155 derece'], 'İki teğetin oluşturduğu dış açı ile değme noktaları arasındaki küçük yayın ölçüleri toplamı 180 derecedir; 180 - 50 = 130 derecedir.'),
  ('Aynı çemberde eş uzunluktaki iki kirişin arkalarında ayırdıkları küçük yayların ölçüleri için ne söylenebilir?', 'Ölçüleri birbirine eşittir', ['Büyük olan yay diğerinin iki katıdır', 'Toplamları her zaman 180 derecedir', 'Farkları merkez açıya eşittir'], 'Bir çemberde eş uzunluktaki kirişler eş ölçülü yaylar ayırır ve merkeze eşit uzaklıktadır.'),
  ('Bir çemberde paralel iki kiriş arasında kalan yayların ölçüleri hakkında aşağıdakilerden hangisi her zaman doğrudur?', 'Yayların ölçüleri birbirine eşittir', ['Yayların toplamı 180 derecedir', 'Yaylardan biri diğerinin iki katıdır', 'Yayların farkı 90 derecedir'], 'Çemberde paralel iki kirişin arasında kalan yayların ölçüleri iç ters çevre açılar yardımıyla birbirine eşit çıkar.'),
  ('Bir çemberin içinde kesişen iki kirişten birinin parçaları 4 birim ve 9 birimdir. Diğer kiriş iki eş parçaya bölündüğüne göre bu ikinci kirişin toplam uzunluğu kaç birimdir?', '12 birim', ['6 birim', '13 birim', '18 birim'], 'İç kuvvet bağıntısına göre x . x = 4 . 9 = 36 buradan x = 6 birim bulunur; kirişin toplam uzunluğu 2x = 12 birimdir.'),
  ('Bir çemberde bir çevre açının ölçüsü ile aynı yayı gören merkez açının ölçüsü toplamı 126 derece olduğuna göre çevre açı kaç derecedir?', '42 derece', ['63 derece', '84 derece', '36 derece'], 'Çevre açıya x dersek merkez açı 2x olur; 3x = 126 dereceden çevre açı x = 42 derece bulunur.'),
  ('Düzlemde doğrusal olmayan üç noktadan kaç farklı çember geçer?', 'Yalnız bir çember geçer', ['Sonsuz sayıda çember geçer', 'Hiçbir çember geçmez', 'Tam olarak iki çember geçer'], 'Doğrusal olmayan üç nokta bir üçgen belirtir ve her üçgenin kenar orta dikmelerinin kesişimini merkez kabul eden tek bir çevrel çemberi vardır.'),
  ('Yarıçapları 5 birim ve 8 birim olan dıştan teğet iki çemberin merkezleri arasındaki uzaklık kaç birimdir?', '13 birim', ['3 birim', '10 birim', '40 birim'], 'Dıştan teğet iki çemberin merkezlerini birleştiren doğru parçası değme noktasından geçer ve uzunluğu yarıçaplar toplamı olan 5 + 8 = 13 birimdir.'),
  ('Bir çemberin dışındaki P noktasından çizilen teğetin değme noktası T\'dir. P\'den geçen kesen çemberi A ve B noktalarında kesiyor. |PA| = 4 birim ve |AB| = 5 birim ise |PT| kaç birimdir?', '6 birim', ['4,5 birim', '8 birim', '9 birim'], 'Teğet-kesen kuvvet bağıntısından |PT|^2 = |PA| . |PB| = 4 . (4 + 5) = 36 bulunur; buradan |PT| = 6 birimdir.'),
  ('Yarıçapı 7 santimetre olan bir çemberin içine çizilebilecek en uzun kiriş kaç santimetredir?', '14 santimetre', ['7 santimetre', '21 santimetre', '10,5 santimetre'], 'Bir çemberdeki en uzun kiriş merkezden geçen çaptır; yarıçap 7 santimetre olduğundan çap 14 santimetredir.'),
  ('Bir çemberde kesişen iki kirişin oluşturduğu iç açının gördüğü yayların ölçüleri 54 derece ve 86 derece olduğuna göre bu iç açının ölçüsü kaç derecedir?', '70 derece', ['32 derece', '68 derece', '140 derece'], 'Çemberde iç açının ölçüsü, gördüğü yayların ölçüleri toplamının yarısına eşittir; (54 + 86) / 2 = 70 derecedir.'),
  ('Bir çembere dışındaki bir noktadan çizilen iki kesenin çember üzerinde ayırdığı ters yönlü yayların ölçüleri 110 derece ve 38 derece ise kesenler arasındaki dış açı kaç derecedir?', '36 derece', ['72 derece', '74 derece', '46 derece'], 'Dış açının ölçüsü, gördüğü büyük yay ile küçük yayın farkının yarısına eşittir; (110 - 38) / 2 = 36 derecedir.'),
  ('Bir çemberin teğet doğrusuna değme noktasından çizilen yarıçap ile teğet doğrusu arasındaki açı kaç derecedir?', '90 derece', ['45 derece', '60 derece', '120 derece'], 'Çemberin merkezinden teğetin değme noktasına çizilen yarıçap, teğet doğrusuna her zaman diktir.'),
  ('Bir kirişler dörtgeninin ardışık üç açısının ölçüleri sırasıyla 75 derece, 100 derece ve 105 derece ise dördüncü açısının ölçüsü kaç derecedir?', '80 derece', ['85 derece', '95 derece', '70 derece'], 'Kirişler dörtgeninde karşılıklı açılar bütünlerdir; ikinci açı olan 100 derecenin karşısındaki dördüncü açı 180 - 100 = 80 derecedir.'),
  ('Merkezi O olan bir çemberde [AB] kirişinin merkeze uzaklığı, [CD] kirişinin merkeze uzaklığından daha küçüktür. Buna göre kiriş uzunlukları için ne söylenebilir?', '|AB| uzunluğu |CD| uzunluğundan büyüktür', ['|CD| uzunluğu |AB| uzunluğundan büyüktür', 'İki kirişin uzunluğu birbirine eşittir', '|AB| kirişi çemberin yarıçapına eşittir'], 'Çemberde merkeze daha yakın olan kirişin uzunluğu, merkeze daha uzak olan kirişten her zaman daha büyüktür.'),
  ('Çapı 10 birim olan bir çemberin çevresi kaç pi birimdir?', '10 pi birim', ['20 pi birim', '25 pi birim', '15 pi birim'], 'Çemberin çevresi pi . çap (2 . pi . r) formülüyle hesaplandığından çapı 10 birim olan çemberin çevresi 10 pi birimdir.'),
  ('Yarıçapı 12 santimetre ve merkez açısı 60 derece olan bir daire diliminin alanı kaç pi santimetrekaredir?', '24 pi santimetrekare', ['12 pi santimetrekare', '36 pi santimetrekare', '48 pi santimetrekare'], 'Daire diliminin alanı pi . r^2 . (alfa / 360) bağıntısından pi . 144 . (60 / 360) = 24 pi santimetrekaredir.'),
  ('Yarıçapı 3 katına çıkarılan bir dairenin alanı ilk durumuna göre kaç katına çıkar?', '9 katına çıkar', ['3 katına çıkar', '6 katına çıkar', '12 katına çıkar'], 'Dairenin alanı yarıçapın karesiyle doğru orantılı olduğundan yarıçap 3 katına çıktığında alan 3^2 = 9 katına çıkar.'),
  ('Merkezleri ortak olan (eş merkezli) iki dairenin yarıçapları 5 birim ve 13 birimdir. Bu iki daire arasında kalan daire halkasının alanı kaç pi birimkaredir?', '144 pi birimkare', ['64 pi birimkare', '169 pi birimkare', '119 pi birimkare'], 'Daire halkasının alanı pi . (R^2 - r^2) bağıntısıyla pi . (169 - 25) = 144 pi birimkare olarak bulunur.'),
  ('Yarıçapı r ve yay uzunluğu L olan bir daire diliminin alanı r ve L cinsinden aşağıdakilerden hangisine eşittir?', '(L . r) / 2', ['L . r', '(L . r^2) / 2', '2 . L . r'], 'Daire diliminin alanı, tabanı yay uzunluğu L ve yüksekliği yarıçap r olan bir üçgen gibi (L . r) / 2 bağıntısıyla hesaplanır.'),
  ('Bir çeyrek dairenin çevresi, yarıçapı 8 santimetre olduğunda kaç santimetredir?', '4 pi + 16 santimetre', ['4 pi santimetre', '8 pi + 16 santimetre', '16 pi + 8 santimetre'], 'Çeyrek dairenin çevresi yay uzunluğu ile iki yarıçapın toplamına eşittir: (2 . pi . 8) / 4 + 8 + 8 = 4 pi + 16 santimetredir.'),
  ('Alanı 49 pi birimkare olan bir dairenin çevresi kaç pi birimdir?', '14 pi birim', ['7 pi birim', '28 pi birim', '21 pi birim'], 'pi . r^2 = 49 pi eşitliğinden yarıçap r = 7 birim bulunur; çevre ise 2 . pi . 7 = 14 pi birimdir.'),
  ('Bir kenar uzunluğu 10 santimetre olan karenin kenarlarına içten teğet olan dairenin alanı kaç pi santimetrekaredir?', '25 pi santimetrekare', ['100 pi santimetrekare', '50 pi santimetrekare', '20 pi santimetrekare'], 'Karenin iç teğet daire çapı karenin kenarına (10 santimetreye) eşit olduğundan yarıçap 5 santimetre ve alan 25 pi santimetrekaredir.'),
  ('Çevresi sayıca alanına eşit olan bir dairenin yarıçapı kaç birimdir?', '2 birim', ['1 birim', '4 birim', '2 pi birim'], '2 . pi . r = pi . r^2 eşitliğinde her iki taraf pi . r ile sadeleştirildiğinde yarıçap r = 2 birim elde edilir.'),
  ('Yarıçapı 8 birim ve yay uzunluğu 7 pi birim olan bir daire diliminin alanı kaç pi birimkaredir?', '28 pi birimkare', ['56 pi birimkare', '14 pi birimkare', '32 pi birimkare'], 'Dilim alanı (yay uzunluğu . yarıçap) / 2 bağıntısından (7 pi . 8) / 2 = 28 pi birimkare bulunur.'),
  ('Merkez açısı 45 derece olan bir daire diliminin alanı, aynı dairenin tam alanının kaçta kaçıdır?', 'Sekizde biridir', ['Altıda biridir', 'Dörtte biridir', 'Dokuzda biridir'], 'Tam daire 360 derece olduğundan 45 derecelik dilim 45 / 360 = 1/8 oranında yani tam alanın sekizde biridir.'),
  ('Yarıçapı 3 santimetre olan silindir biçimindeki bir makaraya gergin bir ip tek sıra halinde 10 tam tur sarıldığında sarılan ipin uzunluğu kaç pi santimetre olur?', '60 pi santimetre', ['30 pi santimetre', '90 pi santimetre', '45 pi santimetre'], 'Her bir tam turda makaranın çevresi kadar (2 . pi . 3 = 6 pi santimetre) ip sarılır; 10 turda toplam 60 pi santimetre ip sarılır.'),
  ('Aynı uzunluktaki bir telle önce bir çember, sonra bir kare oluşturuluyor. Hangisinin sınırladığı bölgenin alanı daha büyüktür?', 'Çemberin sınırladığı daire alanı daha büyüktür', ['Karenin sınırladığı alan daha büyüktür', 'İkisinin sınırladığı alanlar birbirine eşittir', 'Telin uzunluğuna göre büyüklük sıralaması değişir'], 'İzoperimetrik eşitsizliğe göre sabit çevre uzunluğuna sahip kapalı düzlemsel şekiller arasında en büyük alana sahip olan dairedir.'),
  ('Bir dairenin içine çizilen karenin köşegeni 8 kök 2 birim olduğuna göre bu çevrel dairenin alanı kaç pi birimkaredir?', '32 pi birimkare', ['64 pi birimkare', '16 pi birimkare', '48 pi birimkare'], 'Karenin köşegeni dairenin çapına eşittir; 2r = 8 kök 2 olduğundan r = 4 kök 2 birim ve daire alanı pi . (4 kök 2)^2 = 32 pi birimkaredir.'),
  ('Yarıçapları oranı 2/5 olan iki çemberin çevreleri oranı ile sınırladıkları dairelerin alanları oranı toplamı kaçtır?', '14/25', ['4/25', '9/25', '12/25'], 'Benzerlik oranından çevreler oranı 2/5 ve alanlar oranı (2/5)^2 = 4/25 olur; toplamları 10/25 + 4/25 = 14/25 bulunur.'),
  ('Dışbükey (konveks) bir çokgenin dış açılarının ölçüleri toplamı kenar sayısından bağımsız olarak kaç derecedir?', '360', ['180 derece olup kenar sayısıyla doğru orantılıdır', '540 derece olup iç açılar toplamının yarısıdır', '720 derece olup köşegen sayısına bağlıdır'], 'Dışbükey tüm çokgenlerin dış açılarının ölçüleri toplamı kenar sayısına bağlı olmaksızın daima 360 derecedir.'),
  ('Bir iç açısının ölçüsü 140 derece olan düzgün çokgenin kenar sayısı kaçtır?', '9', ['8 kenarlı düzgün sekizgen', '10 kenarlı düzgün ongen', '12 kenarlı düzgün onikigen'], 'İç açısı 140 derece ise dış açısı 180 - 140 = 40 derecedir; kenar sayısı n = 360 / 40 = 9 bulunur.'),
  ('İç açılarının ölçüleri toplamı 1260 derece olan dışbükey çokgenin bir köşesinden çizilebilen köşegen sayısı kaçtır?', '6', ['7 adet farklı köşegen çizilebilir', '8 adet farklı köşegen çizilebilir', '9 adet farklı köşegen çizilebilir'], '(n - 2) * 180 = 1260 eşitliğinden n - 2 = 7 ve n = 9 bulunur; bir köşeden çizilen köşegen sayısı n - 3 = 6 olur.'),
  ('Bir kenar uzunluğu 6 cm olan düzgün altıgenin alanı kaç santimetrekaredir?', '54*kök(3)', ['36*kök(3) santimetrekare kadardır', '72*kök(3) santimetrekare kadardır', '48*kök(3) santimetrekare kadardır'], 'Düzgün altıgen 6 adet eşkenar üçgenden oluşur; alan = 6 * (6^2 * kök(3) / 4) = 54*kök(3) santimetrekaredir.'),
  ('Bir düzgün çokgenin bir iç açısının ölçüsünün bir dış açısının ölçüsüne oranı 5 olduğuna göre bu çokgen kaç kenarlıdır?', '12', ['10 kenarlı düzgün bir çokgendir', '15 kenarlı düzgün bir çokgendir', '18 kenarlı düzgün bir çokgendir'], 'Dış açıya x denirse iç açı 5x olur; 6x = 180 eşitliğinden dış açı x = 30 derece ve kenar sayısı 360 / 30 = 12 bulunur.'),
  ('Alt tabanı 14 cm ve üst tabanı 6 cm olan bir yamuğun orta taban uzunluğu kaç santimetredir?', '10', ['8 santimetre uzunluğundadır', '12 santimetre uzunluğundadır', '9 santimetre uzunluğundadır'], 'Yamuğun orta taban uzunluğu alt ve üst taban uzunluklarının aritmetik ortalamasıdır: (14 + 6) / 2 = 10 cm.'),
  ('Taban uzunlukları 15 cm ve 9 cm, yüksekliği ise 8 cm olan bir yamuğun alanı kaç santimetrekaredir?', '96', ['84 santimetrekare alana sahiptir', '108 santimetrekare alana sahiptir', '112 santimetrekare alana sahiptir'], 'Yamuğun alanı orta taban ile yüksekliğin çarpımıdır: ((15 + 9) / 2) * 8 = 12 * 8 = 96 santimetrekaredir.'),
  ('Bir paralelkenarda ardışık iki iç açının ölçüleri oranı 2/7 olduğuna göre bu paralelkenarın büyük açısı kaç derecedir?', '140', ['120 derece olan geniş açıdır', '135 derece olan geniş açıdır', '150 derece olan geniş açıdır'], 'Paralelkenarda ardışık iki açının toplamı 180 derecedir; 2k + 7k = 180 eşitliğinden k = 20 ve büyük açı 7 * 20 = 140 derece bulunur.'),
  ('Kenar uzunlukları 10 cm ve 16 cm olan bir paralelkenarın uzun kenarına ait yüksekliği 5 cm olduğuna göre kısa kenarına ait yüksekliği kaç santimetredir?', '8', ['6 santimetre uzunluğundadır', '10 santimetre uzunluğundadır', '7,5 santimetre uzunluğundadır'], 'Paralelkenarın alanı her iki taban ve o tabana ait yüksekliğin çarpımına eşittir: 16 * 5 = 10 * h eşitliğinden h = 8 cm bulunur.'),
  ('Köşegen uzunlukları 16 cm ve 12 cm olan bir eşkenar dörtgenin çevresi kaç santimetredir?', '40', ['36 santimetre uzunluğundadır', '48 santimetre uzunluğundadır', '56 santimetre uzunluğundadır'], 'Eşkenar dörtgende köşegenler birbirini dik ortalar; 6-8-10 dik üçgeninden bir kenar uzunluğu 10 cm ve çevre 4 * 10 = 40 cm bulunur.'),
  ('Bir kenar uzunluğu 10 cm ve geniş açısı 150 derece olan eşkenar dörtgenin alanı kaç santimetrekaredir?', '50', ['50*kök(3) santimetrekare kadardır', '100 santimetrekare alana sahiptir', '25*kök(3) santimetrekare kadardır'], 'Geniş açısı 150 derece ise dar açısı 30 derecedir; eşkenar dörtgenin alanı a^2 * sin30 = 100 * (1/2) = 50 santimetrekaredir.'),
  ('Köşegen uzunluğu 8*kök(2) cm olan bir karenin alanı kaç santimetrekaredir?', '64', ['32 santimetrekare alana sahiptir', '128 santimetrekare alana sahiptir', '48 santimetrekare alana sahiptir'], 'Köşegen uzunluğu a*kök(2) = 8*kök(2) olduğundan karenin bir kenarı a = 8 cm ve alanı 8^2 = 64 santimetrekaredir.'),
  ('Çevresi 36 cm olan bir dikdörtgenin kısa kenarı 7 cm olduğuna göre bu dikdörtgenin alanı kaç santimetrekaredir?', '77', ['63 santimetrekare alana sahiptir', '84 santimetrekare alana sahiptir', '91 santimetrekare alana sahiptir'], 'Yarı çevre 36 / 2 = 18 cm olduğundan uzun kenar 18 - 7 = 11 cm ve alan 7 * 11 = 77 santimetrekaredir.'),
  ('Köşegen uzunlukları 10 cm ve 18 cm olan bir deltoidin alanı kaç santimetrekaredir?', '90', ['180 santimetrekare alana sahiptir', '80 santimetrekare alana sahiptir', '120 santimetrekare alana sahiptir'], 'Deltoidin köşegenleri birbirini dik kestiğinden alanı köşegen uzunlukları çarpımının yarısıdır: (10 * 18) / 2 = 90 santimetrekaredir.'),
  ('Köşegenleri birbirine dik kesişen dışbükey bir ABCD dörtgeninde |AB| = 5 cm, |BC| = 9 cm ve |CD| = 8 cm olduğuna göre |DA| kenarının uzunluğu kaç santimetredir?', '2*kök(2)', ['3*kök(2) santimetre uzunluğundadır', 'kök(10) santimetre uzunluğundadır', '4 santimetre uzunluğundadır'], 'Köşegenleri dik kesişen dörtgenlerde karşılıklı kenarların kareleri toplamı birbirine eşittir: 5^2 + 8^2 = 9^2 + |DA|^2 eşitliğinden 89 = 81 + |DA|^2 ve |DA| = 2*kök(2) cm bulunur.'),
  ('Bir düzgün onikigenin bir köşesinden geçen simetri ekseni sayısı ile tüm düzgün onikigenin toplam simetri ekseni sayısı sırasıyla kaçtır?', '1 ve 12', ['2 ve 24 adet simetri ekseni', '1 ve 6 adet simetri ekseni', '2 ve 12 adet simetri ekseni'], 'Çift kenarlı düzgün çokgenlerde karşılıklı köşelerden n/2 ve karşılıklı kenar orta noktalarından n/2 olmak üzere toplam n = 12 simetri ekseni vardır; her köşeden yalnız 1 simetri ekseni geçer.'),
  ('Köşegenlerinin kesim noktası simetri merkezi olan ancak kenar ve açı eşitliği şartı taşımayan dörtgen ailesinin en genel üyesi aşağıdakilerden hangisidir?', 'Paralelkenar', ['İkizkenar yamuk şeklindeki dörtgen', 'Dışbükey deltoid şeklindeki dörtgen', 'Çeşitkenar dik yamuk dörtgeni'], 'Köşegenleri birbirini ortalayan yani kesim noktası noktasal simetri merkezi olan en genel dörtgen paralelkenardır.'),
  ('Bir karenin kenar uzunlukları %20 oranında artırıldığında elde edilen yeni karenin alanı başlangıçtaki karenin alanına göre yüzde kaç artar?', '44', ['40 oranında artış gösterir', '20 oranında artış gösterir', '48 oranında artış gösterir'], 'Kenar uzunluğu 10 birimden 12 birime çıktığında alan 100 birimkareden 144 birimkareye yükselir; artış oranı %44 olur.'),
  ('Bir dışbükey ongenin iç açılarının ölçüleri toplamı kaç dik açıya (90 dereceye) eşittir?', '16', ['14 adet dik açıya eşittir', '18 adet dik açıya eşittir', '20 adet dik açıya eşittir'], 'Ongenin iç açıları toplamı (10 - 2) * 180 = 8 * 180 = 16 * 90 derece olduğundan 16 dik açıya eşittir.'),
  ('Köşegenleri birbirini ortalayan ve aynı zamanda köşegen uzunlukları birbirine eşit olan dışbükey dörtgen ailesi aşağıdakilerden hangisidir?', 'Dikdörtgen', ['Geniş açılı çeşitkenar paralelkenar', 'Köşegenleri dik ikizkenar yamuk', 'Simetri eksenli dışbükey deltoid'], 'Köşegenlerin birbirini ortalaması dörtgeni paralelkenar yapar; paralelkenarın köşegenleri birbirine eşit olduğunda ise dikdörtgen elde edilir.'),
  ('İç açılarının ölçüleri toplamı dış açılarının ölçüleri toplamının 4 katı olan dışbükey bir çokgenin toplam köşegen sayısı kaçtır?', '35', ['27 adet köşegene sahiptir', '44 adet köşegene sahiptir', '20 adet köşegene sahiptir'], '(n - 2) * 180 = 4 * 360 = 1440 eşitliğinden n = 10 bulunur; ongenin köşegen sayısı 10 * 7 / 2 = 35\'tir.'),
  ('Bir köşesinden en fazla 9 köşegen çizilebilen dışbükey bir çokgenin kenar sayısı kaçtır?', '12', ['10 kenarlı dışbükey çokgendir', '11 kenarlı dışbükey çokgendir', '13 kenarlı dışbükey çokgendir'], 'Bir köşeden çizilebilen köşegen sayısı n - 3 olduğundan n - 3 = 9 eşitliğinden n = 12 bulunur.'),
  ('Bir dışbükey çokgenin bir köşesinden çizilen tüm köşegenler çokgeni 8 adet üçgensel bölgeye ayırdığına göre bu çokgenin iç açıları toplamı kaç derecedir?', '1440', ['1260 derece olarak hesaplanır', '1620 derece olarak hesaplanır', '1080 derece olarak hesaplanır'], 'Bir köşeden çizilen köşegenler çokgeni n - 2 adet üçgene ayırır; n - 2 = 8 olduğundan iç açılar toplamı 8 * 180 = 1440 derecedir.'),
  ('İçbükey (konkav) bir dörtgen olan bumerang şeklinde (köşeleri A, B, C, D ve D köşesi içbükey) A, B, C dar iç açılarının toplamı 130 derece olduğuna göre dörtgenin D köşesindeki büyük iç açısının ölçüsü kaç derecedir?', '230', ['130 derece olan geniş açıdır', '210 derece olan refleks açıdır', '250 derece olan refleks açıdır'], 'Konkav dörtgende bile iç açılar toplamı (4 - 2) * 180 = 360 derecedir; D iç açısı 360 - 130 = 230 derecedir (dışta kalan dar/geniş yuva açısı ise 130 derecedir).'),
  ('Dışbükey bir ABCD dörtgeninde komşu olan A ve B iç açılarının açıortayları E noktasında kesişmektedir. C açısı 110 derece ve D açısı 70 derece olduğuna göre AEB açısının ölçüsü kaç derecedir?', '90', ['80 derece olan dar açıdır', '100 derece olan geniş açıdır', '95 derece olan geniş açıdır'], 'Komşu iki açının açıortayları arasında kalan açının ölçüsü diğer iki iç açının ölçüleri toplamının yarısına eşittir: (110 + 70) / 2 = 90 derecedir.'),
  ('Bir paralelkenarın alanı 90 santimetrekare olduğuna göre köşegenlerden birinin paralelkenarı ayırdığı eş üçgenlerden birinin alanı kaç santimetrekaredir?', '45', ['30 santimetrekare alana sahiptir', '60 santimetrekare alana sahiptir', '22,5 santimetrekare alana sahiptir'], 'Paralelkenarda her bir köşegen alanı birbirine eş iki üçgensel bölgeye ayırır: 90 / 2 = 45 santimetrekaredir.'),
  ('Bir eşkenar dörtgenin bir köşegeni iç açılardan birini 35 derecelik açıyla böldüğüne göre bu eşkenar dörtgenin geniş açısının ölçüsü kaç derecedir?', '110', ['120 derece olan geniş açıdır', '105 derece olan geniş açıdır', '140 derece olan geniş açıdır'], 'Eşkenar dörtgende köşegenler iç açıortaydır; dar açı 2 * 35 = 70 derece olduğundan geniş açı 180 - 70 = 110 derece bulunur.'),
  ('Bir deltoidde simetri ekseni olmayan köşegenin uç noktalarındaki karşılıklı iki iç açının ölçüleri hakkında aşağıdakilerden hangisi her zaman doğrudur?', 'Ölçüleri birbirine eşittir', ['Ölçüleri toplamı daima 180 derecedir', 'Biri diğerinin daima iki katıdır', 'Her ikisi de mutlaka 90 derecedir'], 'Deltoidin simetri ekseni şekli iki eş üçgene ayırdığından, simetri ekseni üzerinde bulunmayan karşılıklı iki köşenin iç açıları birbirine eşittir.'),
  ('Düzgün beşgenin bir dış açısının ölçüsü kaç derecedir?', '72', ['60 derece olan dar açıdır', '108 derece olan geniş açıdır', '54 derece olan dar açıdır'], 'Düzgün beşgenin dış açıları toplamı 360 derece olduğundan bir dış açısı 360 / 5 = 72 derecedir.'),
  ('Köşegen uzunlukları 14 cm ve 18 cm olan ve köşegenleri birbirini dik kesen dışbükey bir dörtgenin alanı kaç santimetrekaredir?', '126', ['252 santimetrekare alana sahiptir', '112 santimetrekare alana sahiptir', '144 santimetrekare alana sahiptir'], 'Köşegenleri dik kesişen herhangi bir dörtgenin alanı köşegenler çarpımının yarısıdır: (14 * 18) / 2 = 126 santimetrekaredir.'),
  ('Bir paralelkenarın dört iç açıortayının kesim noktalarının oluşturduğu dörtgen (paralelkenar eşkenar dörtgen değilken) her zaman hangi özel dörtgendir?', 'Dikdörtgen', ['Kenarları eşit eşkenar dörtgen', 'Köşegenleri dik dışbükey deltoid', 'Tabanları farklı ikizkenar yamuk'], 'Paralelkenarda ardışık iki açının toplamı 180 derece olduğundan komşu açıortaylar birbirini 90 derecelik açıyla keser; dört köşesi de 90 derece olan ve kenarları farklı uzunlukta olan bu dörtgen bir dikdörtgendir.'),
  ('Çevresi 68 cm olan bir eşkenar dörtgenin köşegenlerinden birinin uzunluğu 30 cm olduğuna göre alanı kaç santimetrekaredir?', '240', ['120 santimetrekare alana sahiptir', '255 santimetrekare alana sahiptir', '270 santimetrekare alana sahiptir'], 'Bir kenarı 68 / 4 = 17 cm ve yarı köşegeni 15 cm olduğundan 8-15-17 dik üçgeninden diğer yarı köşegen 8 cm yani köşegen 16 cm olur; alan (30 * 16) / 2 = 240 santimetrekaredir.'),
  ('Kısa kenarı 5 cm ve köşegen uzunluğu 13 cm olan bir dikdörtgenin çevresi kaç santimetredir?', '34', ['30 santimetre uzunluğundadır', '36 santimetre uzunluğundadır', '60 santimetre uzunluğundadır'], '5-12-13 dik üçgeninden uzun kenar 12 cm bulunur; çevre 2 * (5 + 12) = 34 cm\'dir.'),
  ('Bir düzgün dokuzgenin bir iç açısının ölçüsü bir düzgün altigenin bir iç açısının ölçüsünden kaç derece fazladır?', '20', ['15 derece daha fazladır', '25 derece daha fazladır', '30 derece daha fazladır'], 'Düzgün dokuzgenin bir iç açısı 180 - (360/9) = 140 derece, düzgün altıgenin bir iç açısı 120 derecedir; farkları 140 - 120 = 20 derecedir.'),
  ('Bir deltoidin simetri ekseni olan köşegeni için aşağıdakilerden hangisi yanlıştır?', 'Diğer köşegen tarafından her zaman iki eş parçaya bölünür', ['Uç noktalarındaki iç açıları iki eş parçaya böler', 'Diğer köşegeni dik açıyla iki eş parçaya böler', 'Deltoidi alanları birbirine eşit iki eş üçgene ayırır'], 'Deltoidde simetri ekseni diğer köşegeni dik ortalar ancak kendisi (eşkenar dörtgen olmadığı sürece) diğer köşegen tarafından iki eş parçaya bölünmez.'),
  ('Bir dışbükey yedigenin dış açılarından altısının ölçüleri toplamı 305 derece olduğuna göre yedinci köşedeki iç açının ölçüsü kaç derecedir?', '125', ['115 derece olan geniş açıdır', '135 derece olan geniş açıdır', '55 derece olan dar açıdır'], 'Dış açılar toplamı 360 derece olduğundan yedinci dış açı 360 - 305 = 55 derecedir; komşu bütünleri olan iç açı 180 - 55 = 125 derecedir.'),
  ('Karşılıklı kenar çiftlerinden en az biri paralel olan dörtgenlere genel olarak ne ad verilir?', 'Yamuk', ['Paralelkenar ailesi dörtgenleri', 'Deltoid tipi simetrik dörtgenler', 'Eşkenar dörtgen tipi çokgenler'], 'En az bir çift karşılıklı kenarı birbirine paralel olan dörtgenlerin en genel tanımı yamuktur.'),
  ('Bir eşkenar dörtgenin simetri ekseni sayısı kaçtır (kare olmayan genel bir eşkenar dörtgen için)?', '2', ['4 adet simetri ekseni vardır', '1 adet simetri ekseni vardır', 'Hiç simetri ekseni bulunmaz'], 'Kare olmayan bir eşkenar dörtgende yalnızca iki köşegen doğrusu şeklin katlama (yansıma) simetri eksenidir; kenar orta dikmeleri simetri ekseni değildir.'),
  ('Köşegenleri eşit uzunlukta olan bir eşkenar dörtgenin her bir iç açısının ölçüsü kaç derecedir?', '90', ['60 derece olan dar açıdır', '120 derece olan geniş açıdır', '45 derece olan dar açıdır'], 'Eşkenar dörtgen aynı zamanda bir paralelkenardır; köşegenleri birbirine eşit olan paralelkenar dikdörtgen olduğundan hem eşkenar dörtgen hem dikdörtgen özelliğini taşıyan bu şekil karedir ve her iç açısı 90 derecedir.'),
  ('Çapı 16 santimetre olan bir daire diliminin merkez açısı 90 derece ise bu çeyrek dairenin alanı kaç pi santimetrekaredir?', '16 pi santimetrekare', ['64 pi santimetrekare', '32 pi santimetrekare', '24 pi santimetrekare'], 'Çap 16 santimetre olduğundan yarıçap 8 santimetredir; çeyrek daire alanı (pi . 8^2) / 4 = 16 pi santimetrekaredir.'),
];
